import{_ as d,h as n,i as e,c,v as o,p as r,x as t,m as i,e as s,S as p}from"./chunks/framework.Dvtg8yj2.js";const g=JSON.parse('{"title":"GGUF / k-quants","description":"","frontmatter":{"title":"GGUF / k-quants","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/gguf.md","filePath":"llm/gguf.md","lastUpdated":1788454257000}'),m={name:"llm/gguf.md"};function G(_,a,u,E,h,A){const l=n("Mermaid");return e(),c("div",null,[a[1]||(a[1]=o('<h1 id="gguf-k-quants" tabindex="-1">GGUF / k-quants <a class="header-anchor" href="#gguf-k-quants" aria-label="Permalink to &quot;GGUF / k-quants&quot;">​</a></h1><div class="epigraph"><p>GGUF 是一份可 mmap 的张量容器：量化类型、分词器与超参写在元数据里；k-quant 用超级块上的多层尺度，把异常值关进比 Q4_0 更细的格子，而不需要 GPTQ 那种离线 Hessian。</p><footer>—— ggml / llama.cpp 的 GGUF 规范与 k-quant 实现说明</footer></div><p>本地推理要把模型当成一个文件打开，而不是先起 Python、再把 safetensors 解成半精度再临时量化。GGUF（GPT-Generated Unified Format）是 ggml 生态用来替换早期混乱 <code>.bin</code> / GGML 文件的容器：魔数、版本、键值元数据、张量信息、然后是按块存放的量化权重。k-quant（<code>Q2_K</code> … <code>Q6_K</code>，以及常见的 <code>Q4_K_M</code> 配方）是写在这种容器里的一族<strong>分块量化数据类型</strong>，用 256 权重量级的超级块、块内再分组，配不同精度的尺度，减轻老式 <code>Q4_0</code> 一块一个 scale 对异常通道的伤害。它不是一篇 ICLR 论文里的新目标函数，而是 llama.cpp 里为 CPU / Metal / CUDA 核写出来的存储与计算布局。质量与速度必须锁定量化类型再比；「GGUF 模型」只说明容器，不说明比特。运行时故事见 <a href="/llm/llamacpp">llama.cpp / ggml</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>早期 GGML 二进制随量化方案迭代，转换脚本与加载器经常互不认。模型还要把词表、RoPE 基、架构名、量化版本放在一起，否则 mmap 到一半才发现缺 tokenizer。需要一种带版本的容器：新加载器能跳过不认识的元数据键，旧文件能报错而不是静默错。这是 GGUF 要解的<strong>分发</strong>问题。</p><p>量化问题是另一轴。<code>Q4_0</code> 一类方案把 32 个权重共用一个 FP16 尺度，异常值把尺度拉大，同块其余权重的有效比特变少，困惑度在 7B 上已经刺手。GPTQ / AWQ 用校准去保护显著方向，但依赖 Python 量化流水线与特定 GPU 核，和 ggml 的「打开文件就开始 matmul」不吻合。k-quant 要在<strong>纯分块、可 SIMD 反量化</strong>的约束下，用更多的尺度比特换异常值鲁棒性，并且让转换在 CPU 上对任意 HF 权重跑完，不必解 Hessian。</p><h3 id="容器与码本不要互相替代" tabindex="-1">容器与码本不要互相替代 <a class="header-anchor" href="#容器与码本不要互相替代" aria-label="Permalink to &quot;容器与码本不要互相替代&quot;">​</a></h3><p>GGUF 可以装 FP16、<code>Q8_0</code>、k-quant、甚至后续的 i-quant 等。说「转成 GGUF」没有指定误差。反过来，k-quant 的内存布局也可以出现在别的封装里，但生态事实是它和 GGUF + llama.cpp 核绑在一起。评测必须写 <code>Q4_K_M</code> 或 <code>Q5_K_S</code> 这种全名；只写 GGUF 与只写 4-bit 一样无信息。</p><p><span class="marginnote">GGUF 不负责训练。LoRA 要先合并再量化，或使用运行时对适配器的有限支持。在线改权重、多适配器并发，不是这个格式的设计中心，服务端见 vLLM 多 LoRA。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>文件布局公开且故意简单：文件头魔数 <code>GGUF</code>、版本号、张量个数、元数据键值对（字符串、数、数组），然后每个张量的名字、形状、量化类型、数据偏移。加载器按偏移 mmap，decode 时按块把量化权重与尺度读进 SIMD 寄存器，反量化成浮点乘激活，或走为该类型特化的整数点积。分词器与 chat template 应写进元数据，避免「权重对了、模板错了」。</p><p>k-quant 的方法是超级块。以常见的 256 个权重为一个 super-block：内部再切成 8 个 32 元组。超级块上存一份较粗的尺度，每个 32 元组再存更细的尺度或量化后的尺度；权重本身用 2–6 bit。异常值被限制在 32 这一档的尺度里，不再污染整整 256 个位置。<code>Q4_K</code> 是 4-bit 权这一档的代表；<code>Q5_K</code>、<code>Q6_K</code> 加比特换质量。配方后缀 <code>_S</code> / <code>_M</code> / <code>_L</code> 不是另三种格子，而是<strong>哪些张量用更低比特、哪些张量（如 <code>attn_v</code>、<code>ffn_down</code>）留更高比特</strong>的混合方案。<code>Q4_K_M</code> 成为社区默认，是经验上体积、PPL、核效率的折中，不是理论上的最优码本。</p>',12)),(e(),r(p,null,{default:t(()=>[s(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20HF%5B%22HF%20%E6%9D%83%E9%87%8D%22%5D%20--%3E%20CVT%5B%22%E8%BD%AC%E6%8D%A2%E8%84%9A%E6%9C%AC%E9%80%89%20quant%20%E7%B1%BB%E5%9E%8B%22%5D%0A%20%20CVT%20--%3E%20F%5B%22GGUF%EF%BC%9A%E5%85%83%E6%95%B0%E6%8D%AE%20%2B%20%E5%88%86%E5%9D%97%E5%BC%A0%E9%87%8F%22%5D%0A%20%20F%20--%3E%20MMAP%5B%22mmap%22%5D%0A%20%20MMAP%20--%3E%20K%5B%22k-quant%20%E8%B6%85%E7%BA%A7%E5%9D%97%22%5D%0A%20%20K%20--%3E%20SB%5B%22256%20%E6%9D%83%3A%20%E7%B2%97%E5%B0%BA%E5%BA%A6%22%5D%0A%20%20SB%20--%3E%20BL%5B%2232%20%E6%9D%83%3A%20%E7%BB%86%E5%B0%BA%E5%BA%A6%20%2B%20%E4%BD%8E%E6%AF%94%E7%89%B9%E6%A0%BC%E5%AD%90%22%5D%0A%20%20BL%20--%3E%20KER%5B%22%E5%90%8E%E7%AB%AF%E7%89%B9%E5%8C%96%20matmul%22%5D%0A%20%20KER%20--%3E%20TOK%5B%22decode%20%E4%B8%80%E4%B8%AA%20token%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>转换通常是离线、一次、非 GPTQ：对每块估 min/max 或绝对最大值，写入尺度与量化整数。也可以先做 GPTQ/AWQ 再塞进 GGUF，那是两条流水线的串联，质量归因要写清楚，不能把 GPTQ 的 PPL 标成「k-quant 的结果」。推理激活一般是 FP16/FP32 或按后端的 8-bit，和权重 k-quant 独立。</p><h3 id="核决定墙钟-比特不决定" tabindex="-1">核决定墙钟，比特不决定 <a class="header-anchor" href="#核决定墙钟-比特不决定" aria-label="Permalink to &quot;核决定墙钟，比特不决定&quot;">​</a></h3><p>同一份 <code>Q4_K_M</code>，CPU AVX、ARM NEON、Metal、CUDA 的实现完整度不同。有特化核的类型可以比「比特更低但走标量反量化」的类型更快。因此 <code>Q3_K</code> 不必比 <code>Q4_K</code> 快，<code>Q4_0</code> 有时在某后端反而更快。选类型要看该设备的核表与你的 PPL 预算，而不是看字母顺序。Apple 统一内存上，mmap 量化块少一次拷贝，这是 GGUF 本地路径相对「CUDA + 独立显存 + safetensors」的结构差，不是算法差。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分块仿射量化的误差是块内动态范围决定的。超级块机制把动态范围的估计拆成两级：粗尺度管 256 这个窗口的总能量，细尺度管 32 这个窗口里的局部尖峰。相对单尺度 <code>Q4_0</code>，异常通道的 \\(s\\) 不再统治整块。这与 AWQ 用全局通道 \\(s\\) 保护显著列、GPTQ 用 Hessian 补偿，是三条不同的误差控制：k-quant 不看校准任务，只看这块权重自己的统计，故转换快、对任务中立，也故不能在「这一列对语言建模特别重要」的意义上做针对性保护——它保护的是数值尖峰，不是语义显著。</p><p>mmap 机制：操作系统按页载入正在 matmul 的那些块，冷启动不必把 70B 的 4-bit 一次打进进程堆。这是本地助手能在 16–32 GB 内存上跑 30B 量化模型的前提之一。服务端高并发若随机访问所有层的所有块，页缓存行为不同，GGUF 不是为多租户吞吐设计的。</p><p><span class="marginnote"><code>Q4_K_M</code> 的 M 表示 mixed：重要张量更胖。把所有张量都打成同一 <code>Q4_K</code> 体积会更小、PPL 通常更差。比较必须锁定配方全名。</span></p><p>与 <a href="/llm/qlora">QLoRA</a> 的 NF4：NF4 是正态分位数码本，面向训练期冻结基座；k-quant 是均匀/近均匀格子加多级尺度，面向 ggml 反量化核。两者都叫 4-bit，网格不同，不能当同一检查点。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要用一份公开的 <code>Q4_K_M</code> 聊天体感代替领域评测。转换常用通用校准或甚至无校准分块，长尾专有名词、代码、多语言可能先糊。需要任务对齐时，应在同一 GGUF 类型上用你的集测，或改走 GPTQ/AWQ 再转换并声明。新架构（MLA、奇异 MoE）要等 ggml 实现算子与 quant 核，窗口期内只有 Python 引擎能跑，这不是 GGUF 的错。</p><p>许可证：格式与加载器是开源仓库的 MIT 一类许可；模型权重另有各家协议。量化不改变权证。安全上，GGUF 可含自定义元数据，加载不可信文件与加载不可信 pickle 类似，应限来源。</p><p><span class="marginnote">出处是 <a href="https://github.com/ggerganov/ggml" target="_blank" rel="noreferrer">https://github.com/ggerganov/ggml</a> 的 GGUF 说明与 llama.cpp 量化文档，不要给 k-quant 编造 arXiv。社区博客里的 PPL 表要核对该日的 commit 与模型，布局改过不止一次。</span></p><p>服务引擎（vLLM、TRT-LLM）有自己的 GPTQ/AWQ/FP8 布局。GGUF 作为主格式出现在本地与部分兼容层；集群上为了核性能通常会再转一份。选 GGUF 的理由是：一份文件、多后端、mmap、k-quant 在 CPU 上足够好。选它当数据中心唯一格式，会把 GPU Tensor Core 的 INT4/FP8 路径让出去。</p><h3 id="元数据里的词表与-rope-必须跟权重同一次转换" tabindex="-1">元数据里的词表与 RoPE 必须跟权重同一次转换 <a class="header-anchor" href="#元数据里的词表与-rope-必须跟权重同一次转换" aria-label="Permalink to &quot;元数据里的词表与 RoPE 必须跟权重同一次转换&quot;">​</a></h3><p>GGUF 把 tokenizer 模型、特殊 token、RoPE 基频、架构字符串和量化类型放在同一文件，是为了避免「权重是 Llama-3、词表还是 Llama-2」。转换脚本若只搬张量、用加载器默认词表，chat template 会对不齐，模型看起来像量化坏了。k-quant 改的是权重格子，改不了分词。排查「量化后变笨」要先 diff 元数据键，再去调 <code>Q5_K_M</code> 换 <code>Q6_K</code>。新版本 GGUF 增加的键，旧加载器应忽略；缺的关键键应硬失败，而不是用静默默认。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GGUF 是 ggml 的带元数据张量容器，为 mmap 与跨版本分发，不是量化算法本身。</li><li>k-quant 用超级块多层尺度做 2–6 bit 权重，缓解 <code>Q4_0</code> 单尺度被异常值绑架。</li><li><code>_S/_M/_L</code> 是不同张量混合比特的配方，<code>Q4_K_M</code> 是常见折中。</li><li>墙钟取决于后端是否为该类型写了核，更低比特不必更快。</li><li>转换默认不看任务显著通道；要任务对齐需另测或串 GPTQ/AWQ。</li><li>与 GPU 生态的 GPTQ/AWQ/SmoothQuant 布局不互换；与 QLoRA NF4 也不互换。</li><li>出处：Georgi Gerganov 及贡献者的 GGUF 规范、llama.cpp 量化类型说明；不编造会议论文。</li></ul>',17))])}const B=d(m,[["render",G]]);export{g as __pageData,B as default};
